"use client"

import { revalidateLogic } from "@tanstack/react-form"
import { type ReactNode, useEffect, useMemo } from "react"

import { FieldGroup } from "@/components/ui/field"
import {
  FormDialog,
  FormDialogBody,
  FormDialogCancel,
  FormDialogDescription,
  FormDialogError,
  FormDialogFooter,
  FormDialogForm,
  FormDialogHeader,
  FormDialogLoadError,
  FormDialogSubmit,
  FormDialogTitle,
} from "@/components/openlmis/form-dialog/form-dialog"
import { useDialogTarget } from "@/components/openlmis/form-dialog/use-dialog-target"
import { useAppForm } from "@/components/openlmis/form-fields/form"
import {
  FieldSkeleton,
  SkeletonLine,
} from "@/components/openlmis/form-fields/form-fields"

import {
  type Lot,
  type LotFormValues,
  type LotProduct,
  lotFormSchema,
  toLotFormValues,
} from "@/components/openlmis/lots-page/lot-form"

const NO_CODES: readonly string[] = []

const TITLE = "Edit Lot"

type LotFormDialogProps = {
  /** The id of the lot to edit; opens the dialog while set. */
  target: string | undefined
  /** The lot being edited; a skeleton shows until it is set. */
  lot?: Lot | undefined
  /** The lot's product: `undefined` while it loads, `null` when no product has the lot's trade item. */
  product?: LotProduct | null | undefined
  /** Shown in place of the product when it could not be loaded. */
  productError?: string | undefined
  /** Codes the server refused as taken by another lot of the product. */
  refusedCodes?: readonly string[]
  /** The lot no longer exists. */
  notFound?: boolean
  /** Loading the lot failed; shows the error with Try Again. */
  onRetry?: (() => void) | undefined
  /** Called with the values; save them, then clear `target` to close. */
  onSubmit: (values: LotFormValues, lot: Lot) => void
  /** Keeps the dialog open and shows a spinner while the lot is saved. */
  pending?: boolean
  /** Shown above the fields, e.g. why the save failed. */
  error?: ReactNode
  onClose: () => void
}

export function LotFormDialog({
  target,
  lot,
  product,
  productError,
  refusedCodes = NO_CODES,
  notFound = false,
  onRetry,
  onSubmit,
  pending = false,
  error,
  onClose,
}: LotFormDialogProps) {
  const { shown, dialogProps } = useDialogTarget(target, onClose)

  return (
    <FormDialog {...dialogProps(pending)}>
      {shown &&
        (notFound ? (
          <>
            <FormDialogHeader>
              <FormDialogTitle>{TITLE}</FormDialogTitle>
              <FormDialogDescription>
                This lot no longer exists.
              </FormDialogDescription>
            </FormDialogHeader>
            <FormDialogFooter>
              <FormDialogCancel>Close</FormDialogCancel>
            </FormDialogFooter>
          </>
        ) : onRetry ? (
          <FormDialogLoadError
            errorTitle="Could Not Load Lot"
            onRetry={onRetry}
            title={TITLE}
          />
        ) : lot === undefined ? (
          <LotFormSkeleton />
        ) : (
          <LotForm
            error={error}
            // Keyed, so opening another lot starts a fresh form.
            key={lot.id}
            lot={lot}
            onSubmit={onSubmit}
            pending={pending}
            product={product}
            productError={productError}
            refusedCodes={refusedCodes}
          />
        ))}
    </FormDialog>
  )
}

function LotProductLine({
  product,
  error,
}: Pick<LotFormDialogProps, "product"> & { error: string | undefined }) {
  if (error) return <FormDialogDescription>{error}</FormDialogDescription>
  if (product === undefined) return <SkeletonLine />
  return (
    <FormDialogDescription>
      {product
        ? `A lot of ${product.fullProductName} (${product.productCode}).`
        : "No product has this lot's trade item."}
    </FormDialogDescription>
  )
}

type LotFormProps = Pick<
  LotFormDialogProps,
  "product" | "productError" | "onSubmit" | "error"
> & {
  lot: Lot
  refusedCodes: readonly string[]
  pending: boolean
}

function LotForm({
  lot,
  product,
  productError,
  refusedCodes,
  onSubmit,
  pending,
  error,
}: LotFormProps) {
  const schema = useMemo(() => lotFormSchema(refusedCodes), [refusedCodes])

  const form = useAppForm({
    defaultValues: toLotFormValues(lot),
    // Quiet until the first submit, then each field re-checks as it is corrected.
    validationLogic: revalidateLogic({
      mode: "submit",
      modeAfterSubmission: "change",
    }),
    validators: { onDynamic: schema },
    onSubmit: ({ value }) => onSubmit(value, lot),
  })

  // A code the server just refused shows its error at once, without another submit.
  useEffect(() => {
    if (refusedCodes.length > 0) void form.validate("change")
  }, [refusedCodes, form])

  return (
    <FormDialogForm onSubmit={form.handleSubmit}>
      <FormDialogHeader>
        <FormDialogTitle>{TITLE}</FormDialogTitle>
        <LotProductLine error={productError} product={product} />
      </FormDialogHeader>
      <FormDialogBody>
        <FieldGroup>
          {error && (
            <FormDialogError description={error} title="Could Not Save Lot" />
          )}
          <form.AppField name="lotCode">
            {(field) => (
              <field.TextField
                autoComplete="off"
                dir="ltr"
                label="Lot Code"
                required
              />
            )}
          </form.AppField>
          <form.AppField name="expirationDate">
            {(field) => (
              <field.DateField
                clearLabel="Clear Expiry Date"
                label="Expiry Date"
                placeholder="Pick A Date"
              />
            )}
          </form.AppField>
          <form.AppField name="manufactureDate">
            {(field) => (
              <field.DateField
                clearLabel="Clear Manufacture Date"
                label="Manufacture Date"
                placeholder="Pick A Date"
              />
            )}
          </form.AppField>
        </FieldGroup>
      </FormDialogBody>
      <FormDialogFooter>
        <FormDialogCancel disabled={pending} />
        <FormDialogSubmit pending={pending}>Save</FormDialogSubmit>
      </FormDialogFooter>
    </FormDialogForm>
  )
}

/** Laid out like the form, so nothing moves when the lot arrives. */
function LotFormSkeleton() {
  return (
    <>
      <FormDialogHeader>
        <FormDialogTitle>{TITLE}</FormDialogTitle>
        <SkeletonLine />
      </FormDialogHeader>
      <FormDialogBody>
        <div aria-busy>
          <FieldGroup>
            <FieldSkeleton label="Lot Code" required />
            <FieldSkeleton label="Expiry Date" />
            <FieldSkeleton label="Manufacture Date" />
          </FieldGroup>
        </div>
      </FormDialogBody>
      <FormDialogFooter>
        <FormDialogCancel />
        <FormDialogSubmit disabled>Save</FormDialogSubmit>
      </FormDialogFooter>
    </>
  )
}

import { z } from "zod"

/** A lot of a product, as OpenLMIS keeps it; dates are `yyyy-MM-dd`. */
export type Lot = {
  id: string
  lotCode: string
  active: boolean
  tradeItemId: string
  expirationDate: string | null
  manufactureDate: string | null
}

/** The product a lot belongs to, found through its trade item. */
export type LotProduct = {
  id: string
  productCode: string
  fullProductName: string
}

const MAX_CODE_LENGTH = 20

// The characters GS1 allows in a lot number, which the server enforces.
const CODE_CHARACTERS = /^[!"%&'()*+,\-./0-9:;<=>?A-Z_a-z]*$/

/** `refusedCodes` are codes the server said another lot of the product has. */
export function lotFormSchema(refusedCodes: readonly string[]) {
  const refused = new Set(refusedCodes.map((code) => code.toLowerCase()))
  return z.object({
    lotCode: z
      .string()
      .refine((code) => code.trim().length > 0, "Enter a lot code.")
      .refine(
        (code) => code.length <= MAX_CODE_LENGTH,
        "Use at most 20 characters."
      )
      .refine(
        (code) => CODE_CHARACTERS.test(code),
        "Use only letters, digits and ! \" % & ' ( ) * + , - . / : ; < = > ? _"
      )
      .refine(
        (code) => !refused.has(code.toLowerCase()),
        "Another lot of this product already has this code."
      ),
    expirationDate: z.string(),
    manufactureDate: z.string(),
  })
}

export type LotFormValues = z.infer<ReturnType<typeof lotFormSchema>>

export function toLotFormValues(lot: Lot): LotFormValues {
  return {
    lotCode: lot.lotCode,
    expirationDate: lot.expirationDate ?? "",
    manufactureDate: lot.manufactureDate ?? "",
  }
}

/** The saved lot with the form's values; an empty date is no date. */
export function toLot(values: LotFormValues, saved: Lot): Lot {
  return {
    ...saved,
    lotCode: values.lotCode,
    expirationDate: values.expirationDate || null,
    manufactureDate: values.manufactureDate || null,
  }
}

"use client"

import type {
  ColumnVisibilityState,
  PaginationState,
} from "@tanstack/react-table"
import { BoxesIcon } from "lucide-react"
import { useCallback, useMemo, useState } from "react"

import {
  useColumnVisibility,
  useContainerSize,
} from "@/components/blocks/openlmis/data-table/responsive-columns"
import type { Lot, LotFormValues } from "@/components/openlmis/lots-page/lot-form"
import { toLot } from "@/components/openlmis/lots-page/lot-form"
import { LotFormDialog } from "@/components/openlmis/lots-page/lot-form-dialog"
import { LOT_HIDEABLE_COLUMNS } from "@/components/openlmis/lots-page/lots"
import { LotsTable } from "@/components/openlmis/lots-page/lots-table"
import { type LotsFilters, LotsToolbar } from "@/components/openlmis/lots-page/lots-toolbar"
import {
  Workspace,
  WorkspaceContent,
  WorkspaceDescription,
  WorkspaceHeader,
  WorkspaceHeading,
  WorkspaceIcon,
  WorkspaceTitle,
} from "@/components/blocks/openlmis/workspace"
import { Callout } from "@/components/openlmis/callout"

import { MOCK_LOTS, MOCK_PRODUCTS } from "@/components/openlmis/lots-page/mock-lots"

const NO_FILTERS: LotsFilters = { product: "", expiryFrom: "", expiryTo: "" }

type Notice = { title: string; description: string }

/** The lots screen; mount it from any route, e.g. the `page.tsx` this template ships. */
export function LotsPage() {
  const [lots, setLots] = useState(MOCK_LOTS)
  const [filters, setFilters] = useState(NO_FILTERS)
  const [pagination, setPagination] = useState<PaginationState>({
    pageIndex: 0,
    pageSize: 10,
  })
  const [typed, setTyped] = useState("")
  const [editing, setEditing] = useState<string>()
  const [refused, setRefused] = useState<string[]>([])
  const [notice, setNotice] = useState<Notice>()
  const [measureContent, contentSize] = useContainerSize<HTMLDivElement>()
  // Kept for the visit only; store it (e.g. in localStorage) to remember it across visits.
  const columnChoices = useState<ColumnVisibilityState>({})
  const columnView = useColumnVisibility(
    LOT_HIDEABLE_COLUMNS,
    columnChoices,
    contentSize
  )

  // Every lot is in memory, so filtering and paging happen here.
  const matching = useMemo(
    () =>
      lots.filter(
        (lot) =>
          (!filters.product || lot.product?.id === filters.product) &&
          (!filters.expiryFrom ||
            (lot.expirationDate !== null &&
              lot.expirationDate >= filters.expiryFrom)) &&
          (!filters.expiryTo ||
            (lot.expirationDate !== null &&
              lot.expirationDate <= filters.expiryTo))
      ),
    [lots, filters]
  )
  const lastPage = Math.max(
    0,
    Math.ceil(matching.length / pagination.pageSize) - 1
  )
  const page = useMemo(
    () => ({
      ...pagination,
      pageIndex: Math.min(pagination.pageIndex, lastPage),
    }),
    [pagination, lastPage]
  )
  const rows = useMemo(
    () =>
      matching.slice(
        page.pageIndex * page.pageSize,
        (page.pageIndex + 1) * page.pageSize
      ),
    [matching, page]
  )

  const query = typed.trim().toLowerCase()
  const found = MOCK_PRODUCTS.filter(
    (product) =>
      !query ||
      product.fullProductName.toLowerCase().includes(query) ||
      product.productCode.toLowerCase().includes(query)
  )
  // The picked product stays first, so the filter can show its name.
  const picked = MOCK_PRODUCTS.find((product) => product.id === filters.product)
  const options = [
    ...(picked ? [picked] : []),
    ...found.filter((product) => product.id !== picked?.id),
  ].map((product) => ({
    value: product.id,
    label: product.fullProductName,
    description: product.productCode,
  }))

  const updateFilters = (patch: Partial<LotsFilters>) => {
    setFilters((current) => ({ ...current, ...patch }))
    setPagination((current) => ({ ...current, pageIndex: 0 }))
  }
  const onEdit = useCallback((id: string) => {
    setNotice(undefined)
    setRefused([])
    setEditing(id)
  }, [])
  const editingLot = lots.find((lot) => lot.id === editing)

  const save = (values: LotFormValues, saved: Lot) => {
    // Lot codes are unique per product, as the server enforces.
    const taken = lots.some(
      (lot) =>
        lot.id !== saved.id &&
        lot.tradeItemId === saved.tradeItemId &&
        lot.lotCode.toLowerCase() === values.lotCode.toLowerCase()
    )
    if (taken) {
      setRefused((codes) => [...codes, values.lotCode])
      return
    }
    setLots((current) =>
      current.map((lot) =>
        lot.id === saved.id ? { ...lot, ...toLot(values, saved) } : lot
      )
    )
    setNotice({
      title: "Lot Saved",
      description: `Changes to ${values.lotCode} are saved.`,
    })
    setEditing(undefined)
  }

  return (
    <Workspace>
      <WorkspaceHeader>
        <WorkspaceHeading>
          <WorkspaceIcon>
            <BoxesIcon />
          </WorkspaceIcon>
          <WorkspaceTitle>Lots</WorkspaceTitle>
          <WorkspaceDescription>
            Batches of products, with their codes and expiry dates.
          </WorkspaceDescription>
        </WorkspaceHeading>
      </WorkspaceHeader>
      <WorkspaceContent>
        {/* Measured, because the room for columns depends on a sidebar as well as the window. */}
        <div
          className="flex flex-col gap-4 @4xl/main:gap-6"
          ref={measureContent}
        >
          {notice && (
            <Callout title={notice.title} tone="success">
              {notice.description}
            </Callout>
          )}
          <LotsToolbar
            columnView={columnView}
            filters={filters}
            onFiltersChange={updateFilters}
            onProductSearch={setTyped}
            productOptions={options}
            productTotal={found.length}
          />
          <LotsTable
            columnVisibility={columnView.visibility}
            filtered={Boolean(
              filters.product || filters.expiryFrom || filters.expiryTo
            )}
            lots={rows}
            onClearFilters={() => updateFilters(NO_FILTERS)}
            onEdit={onEdit}
            onPaginationChange={setPagination}
            pagination={page}
            rowCount={matching.length}
          />
        </div>
      </WorkspaceContent>
      <LotFormDialog
        lot={editingLot}
        onClose={() => setEditing(undefined)}
        onSubmit={save}
        product={editingLot?.product ?? null}
        refusedCodes={refused}
        target={editing}
      />
    </Workspace>
  )
}

"use client"

import {
  createColumnHelper,
  type ColumnVisibilityState,
  functionalUpdate,
  type PaginationState,
  useTable,
} from "@tanstack/react-table"
import { BoxesIcon, EllipsisIcon, PencilIcon, SearchXIcon } from "lucide-react"
import { useCallback, useMemo, useRef } from "react"

import { Button } from "@/components/ui/button"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import {
  DataTable,
  DataTableColumnHeader,
  DataTableEmpty,
  DataTableError,
  type DataTableFeatures,
  DataTablePagination,
  DataTableSkeleton,
  dataTableFeatures,
} from "@/components/blocks/openlmis/data-table/data-table"
import { formatDateValue } from "@/components/openlmis/date-picker/date-value"

import type { LotRow } from "@/components/openlmis/lots-page/lots"

const columnHelper = createColumnHelper<DataTableFeatures, LotRow>()

const muted = (text: string) => (
  <span className="text-muted-foreground">{text}</span>
)

function createColumns(
  dateLanguage: string,
  onEdit: ((id: string) => void) | undefined
) {
  const date = (value: string | null) =>
    value ? formatDateValue(value, dateLanguage) : muted("-")
  return columnHelper.columns([
    columnHelper.accessor((lot) => lot.product?.productCode ?? "", {
      id: "productCode",
      header: ({ column }) => (
        <DataTableColumnHeader column={column} title="Product Code" />
      ),
      cell: ({ getValue }) =>
        getValue() ? (
          <span className="flex">
            <span className="min-w-0 truncate" dir="ltr">
              {getValue()}
            </span>
          </span>
        ) : (
          muted("-")
        ),
      meta: { className: "w-40" },
    }),
    columnHelper.accessor((lot) => lot.product?.fullProductName ?? "", {
      id: "productName",
      header: ({ column }) => (
        <DataTableColumnHeader column={column} title="Product Name" />
      ),
      cell: ({ row, getValue }) =>
        !row.original.product ? (
          muted("No Product")
        ) : getValue() ? (
          <span className="block break-words whitespace-normal" dir="auto">
            {getValue()}
          </span>
        ) : (
          muted("-")
        ),
    }),
    columnHelper.accessor("lotCode", {
      header: ({ column }) => (
        <DataTableColumnHeader column={column} title="Lot Code" />
      ),
      cell: ({ getValue }) => (
        <span className="flex">
          <span className="min-w-0 truncate font-medium" dir="ltr">
            {getValue()}
          </span>
        </span>
      ),
      meta: { className: "w-36 @xl/table:w-44" },
    }),
    columnHelper.accessor("expirationDate", {
      header: ({ column }) => (
        <DataTableColumnHeader column={column} title="Expiry Date" />
      ),
      cell: ({ getValue }) => date(getValue()),
      meta: { className: "w-36" },
    }),
    columnHelper.accessor("manufactureDate", {
      header: ({ column }) => (
        <DataTableColumnHeader column={column} title="Manufacture Date" />
      ),
      cell: ({ getValue }) => date(getValue()),
      meta: { className: "w-40" },
    }),
    ...(onEdit
      ? [
          columnHelper.display({
            id: "actions",
            header: () => <span className="sr-only">Actions</span>,
            cell: ({ row }) => (
              <LotActions lot={row.original} onEdit={onEdit} />
            ),
            meta: { className: "w-16" },
          }),
        ]
      : []),
  ])
}

/** Keeps a closing menu from taking focus back to its trigger when an item opened a dialog, which then owns focus. */
function useMenuOpensDialog() {
  const opened = useRef(false)

  const onOpenChange = useCallback((open: boolean) => {
    if (open) opened.current = false
  }, [])
  const finalFocus = useCallback(() => !opened.current, [])
  const opensDialog = useCallback(
    (open: () => void) => () => {
      opened.current = true
      open()
    },
    []
  )

  return { onOpenChange, finalFocus, opensDialog }
}

function LotActions({
  lot,
  onEdit,
}: {
  lot: LotRow
  onEdit: (id: string) => void
}) {
  const menu = useMenuOpensDialog()

  return (
    <div className="flex justify-end">
      <DropdownMenu onOpenChange={menu.onOpenChange}>
        <DropdownMenuTrigger
          render={
            <Button
              aria-label={`Actions For ${lot.lotCode}`}
              size="icon-sm"
              variant="ghost"
            />
          }
        >
          <EllipsisIcon />
        </DropdownMenuTrigger>
        <DropdownMenuContent
          align="end"
          className="w-auto"
          finalFocus={menu.finalFocus}
        >
          <DropdownMenuItem onClick={menu.opensDialog(() => onEdit(lot.id))}>
            <PencilIcon />
            Edit
          </DropdownMenuItem>
        </DropdownMenuContent>
      </DropdownMenu>
    </div>
  )
}

const ALL_COLUMNS: ColumnVisibilityState = {}

const NO_LOTS: LotRow[] = []

const getRowId = (lot: LotRow) => lot.id

type LotsTableProps = {
  /** One page of lots; a skeleton shows until it is set. */
  lots: readonly LotRow[] | undefined
  /** Every lot that matches the filters, across all pages. */
  rowCount: number
  pagination: PaginationState
  onPaginationChange: (pagination: PaginationState) => void
  columnVisibility?: ColumnVisibilityState
  /** Whether a filter is set, so an empty list offers to clear them. */
  filtered?: boolean
  onClearFilters?: () => void
  /** Without it, the row menu is left out. */
  onEdit?: ((id: string) => void) | undefined
  /** Dims the rows while the next page loads. */
  isStale?: boolean
  /** Loading failed; shows the error with Try Again. */
  onRetry?: (() => void) | undefined
  /** The language dates are shown in. */
  dateLanguage?: string
}

/** Lots with their product and dates, a page at a time; filtering and paging are left to the caller, who must clamp `pageIndex` to the last page when rows shrink. */
export function LotsTable({
  lots,
  rowCount,
  pagination,
  onPaginationChange,
  columnVisibility = ALL_COLUMNS,
  filtered = false,
  onClearFilters,
  onEdit,
  isStale = false,
  onRetry,
  dateLanguage = "en-US",
}: LotsTableProps) {
  const columns = useMemo(
    () => createColumns(dateLanguage, onEdit),
    [dateLanguage, onEdit]
  )
  const table = useTable({
    features: dataTableFeatures,
    columns,
    data: (lots ?? NO_LOTS) as LotRow[],
    getRowId,
    rowCount,
    manualPagination: true,
    manualSorting: true,
    enableSorting: false,
    state: { pagination, columnVisibility },
    onPaginationChange: (updater) =>
      onPaginationChange(functionalUpdate(updater, pagination)),
  })

  if (onRetry)
    return (
      <DataTableError
        description="Something went wrong while loading the lots. Try again."
        onRetry={onRetry}
        title="Could Not Load Lots"
      />
    )
  if (lots === undefined)
    return <DataTableSkeleton rowCount={pagination.pageSize} table={table} />

  return (
    <DataTable
      empty={
        filtered ? (
          <DataTableEmpty
            action={
              onClearFilters && (
                <Button onClick={onClearFilters} variant="destructive">
                  Clear Filters
                </Button>
              )
            }
            description="Try a different product or dates, or clear the filters."
            icon={<SearchXIcon />}
            title="No Matching Lots"
          />
        ) : (
          <DataTableEmpty
            description="Lots appear here once stock is received or counted for them."
            icon={<BoxesIcon />}
            title="No Lots Yet"
          />
        )
      }
      footer={rowCount > 0 && <DataTablePagination table={table} />}
      isStale={isStale}
      table={table}
    />
  )
}

"use client"

import { ListToolbar } from "@/components/blocks/openlmis/list-toolbar"
import {
  type ColumnVisibility,
  ColumnViewOptions,
} from "@/components/openlmis/column-view-options"
import {
  ComboboxFilter,
  type ComboboxFilterOption,
} from "@/components/openlmis/combobox-filter/combobox-filter"
import { DatePicker } from "@/components/openlmis/date-picker/date-picker"

import { LOT_HIDEABLE_COLUMNS } from "@/components/openlmis/lots-page/lots"

export type LotsFilters = {
  /** The product id, or an empty string for any product. */
  product: string
  /** `yyyy-MM-dd`, or an empty string for no bound. */
  expiryFrom: string
  expiryTo: string
}

type LotsToolbarProps = {
  filters: LotsFilters
  onFiltersChange: (patch: Partial<LotsFilters>) => void
  /** The products found for what was typed, with the picked one first. */
  productOptions: ComboboxFilterOption[]
  productTotal?: number
  /** Called with what is typed in the product filter; debounce before searching. */
  onProductSearch?: (text: string) => void
  /** While a search runs, the list says so instead of showing no matches. */
  searching?: boolean
  /** Shown in the list when the product search failed. */
  searchError?: string | undefined
  columnView: {
    visibility: ColumnVisibility
    onVisibilityChange: (visibility: ColumnVisibility) => void
    onReset?: () => void
  }
  dateLanguage?: string
}

/** A product picker, an expiry window and the View menu, above `LotsTable`. */
export function LotsToolbar({
  filters,
  onFiltersChange,
  productOptions,
  productTotal,
  onProductSearch,
  searching = false,
  searchError,
  columnView,
  dateLanguage,
}: LotsToolbarProps) {
  return (
    <ListToolbar>
      <div className="w-full @2xl/toolbar:w-72">
        <ComboboxFilter
          emptyMessage={
            searching ? "Searching..." : (searchError ?? "No Matches")
          }
          label="Product"
          onSearch={onProductSearch}
          onValueChange={(product) => onFiltersChange({ product })}
          options={productOptions}
          total={productTotal}
          value={filters.product}
        />
      </div>
      <div className="min-w-64 flex-1 @2xl/toolbar:max-w-80">
        <DatePicker
          clearLabel="Clear Earliest Expiry Date"
          dateLanguage={dateLanguage}
          id="lots-earliest-expiry"
          label="Earliest Expiry Date"
          latest={filters.expiryTo || undefined}
          onValueChange={(expiryFrom) => onFiltersChange({ expiryFrom })}
          placeholder="Earliest Expiry Date"
          value={filters.expiryFrom}
        />
      </div>
      <div className="min-w-64 flex-1 @2xl/toolbar:max-w-80">
        <DatePicker
          clearLabel="Clear Latest Expiry Date"
          dateLanguage={dateLanguage}
          earliest={filters.expiryFrom || undefined}
          id="lots-latest-expiry"
          label="Latest Expiry Date"
          onValueChange={(expiryTo) => onFiltersChange({ expiryTo })}
          placeholder="Latest Expiry Date"
          value={filters.expiryTo}
        />
      </div>
      <div className="@2xl/toolbar:ms-auto">
        <ColumnViewOptions
          columns={LOT_HIDEABLE_COLUMNS}
          onReset={columnView.onReset}
          onVisibilityChange={columnView.onVisibilityChange}
          visibility={columnView.visibility}
        />
      </div>
    </ListToolbar>
  )
}

